package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class CatalogueWorkflowsAcceptance {
 static String api(String id){return "/api/openservice/catalogue/"+id+"/workflow";}
 static Map<String,Object> result(java.net.http.HttpResponse<byte[]> r)throws Exception{return ProblemInvestigationsAcceptance.result(r);}
 static Map<String,Object> settings(WorkflowSupport h,String id)throws Exception{return result(h.get(api(id),auth("admin")));}
 static Map<String,Object> command(WorkflowSupport h,String id,String operation)throws Exception{return map("operation",operation,"revision",object(settings(h,id).get("offering")).get("revision"));}
 static Map<String,Object> send(WorkflowSupport h,String id,Map<String,Object> body)throws Exception{return result(h.json("POST",api(id),body,auth("admin")));}
 static List<Map<String,Object>> steps(WorkflowSupport h,String id)throws Exception{return objects(object(settings(h,id).get("workflow")).get("steps"));}
 static String add(WorkflowSupport h,String id,String group,String summary)throws Exception{var b=command(h,id,"add");b.putAll(map("summary",summary,"details","Internal instructions: "+summary,"group_id",group));return objects(object(send(h,id,b).get("workflow")).get("steps")).getLast().get("step_id").toString();}
 static void step(WorkflowSupport h,String id,String operation,String step)throws Exception{var b=command(h,id,operation);b.put("step_id",step);send(h,id,b);}
 static String offering(WorkflowSupport h)throws Exception{return CatalogueQuestionsAcceptance.result(h.json("POST","/api/openservice/catalogue",CatalogueAcceptance.offering("Multi-team service",0,true),auth("admin")),201).get("offering_id").toString();}
 static Map<String,Object> orderBody(WorkflowSupport h,String id)throws Exception{return map("revision",object(settings(h,id).get("offering")).get("revision"),"details","Reviewed work","key",Values.id());}
 static String order(WorkflowSupport h,String id,Map<String,Object> body)throws Exception{return CatalogueQuestionsAcceptance.result(h.json("POST","/api/openservice/catalogue/"+id+"/order",body,auth("WorkflowBuyer")),201).get("sys_id").toString();}
 static String tasksApi(String id){return "/api/openservice/records/sc_request/"+id+"/work-tasks";}
 static Map<String,Object> tasks(WorkflowSupport h,String id)throws Exception{return result(h.get(tasksApi(id),auth("admin")));}
 static Map<String,Object> taskBody(WorkflowSupport h,String id,String task,String operation)throws Exception{var p=tasks(h,id);return map("operation",operation,"task_id",task,"revision",WorkTasksAcceptance.task(p,task).get("revision"),"record_revision",ProblemInvestigationsAcceptance.revision(object(p.get("parent"))));}
 static Map<String,Object> act(WorkflowSupport h,String id,String task,String operation,String actor,String value)throws Exception{var b=taskBody(h,id,task,operation);if(operation.equals("complete"))b.put("outcome",value);if(Set.of("cancel","waive").contains(operation))b.put("reason",value);return result(h.json("POST",tasksApi(id),b,auth(actor)));}
 static String state(WorkflowSupport h,String id)throws Exception{return result(h.get("/api/now/table/sc_request/"+id,auth("admin"))).get("state").toString();}
 static Map<String,Object> progress(WorkflowSupport h,String id,String user)throws Exception{return result(h.get("/api/openservice/requests/"+id+"/workflow",auth(user)));}
 static void reconcile(WorkflowSupport h,String id)throws Exception{result(h.json("POST","/api/openservice/requests/"+id+"/workflow",map("record_revision",ProblemInvestigationsAcceptance.revision(object(tasks(h,id).get("parent")))),auth("admin")));}
 static List<String> setup(WorkflowSupport h)throws Exception{for(String u:List.of("WorkflowBuyer","WorkflowOther"))h.account(u,"requester");for(String u:List.of("WorkflowOne","WorkflowTwo"))h.account(u,"agent");var result=new ArrayList<String>();for(String user:List.of("WorkflowOne","WorkflowTwo")){String group=h.add("sys_user_group").get("sys_id").toString(),uid;try(var db=h.store.open()){uid=RecordAccess.owner(db,user);}RecordScopesAcceptance.member(h,group,uid,true);result.add(group);}return result;}
 static void run(WorkflowSupport h)throws Exception{
  var groups=setup(h);String o=offering(h);assertEquals(0,object(settings(h,o).get("workflow")).get("enabled"));String a=add(h,o,groups.get(0),"Prepare <script>"),b=add(h,o,groups.get(1),"Verify delivery");send(h,o,command(h,o,"enable"));var body=orderBody(h,o);String request=order(h,o,body);reconcile(h,request);var ts=objects(tasks(h,request).get("tasks"));assertEquals(2,ts.size());assertEquals(groups.get(0),ts.getFirst().get("group_id"));assertEquals(List.of(ts.getFirst().get("task_id")),ts.getLast().get("predecessors"));assertEquals(2L,((Number)progress(h,request,"WorkflowBuyer").get("remaining")).longValue());assertFalse(progress(h,request,"WorkflowBuyer").toString().contains("Internal instructions"));assertEquals(404,h.get("/api/openservice/requests/"+request+"/workflow",auth("WorkflowOther")).statusCode());assertEquals(403,h.get(tasksApi(request),auth("WorkflowBuyer")).statusCode());assertTrue(html(h.get("/record/sc_request/"+request,auth("WorkflowBuyer"))).contains("0 of 2 steps completed"));
  step(h,o,"up",b);var edit=command(h,o,"edit");edit.putAll(map("step_id",a,"summary","New instructions","details","Changed after order","group_id",groups.get(1)));send(h,o,edit);send(h,o,command(h,o,"disable"));assertEquals(request,order(h,o,body));try(var db=h.store.open()){assertEquals(2,db.count("SELECT COUNT(*) FROM os_case_task WHERE parent_id=?",request));assertEquals(0,db.count("SELECT COUNT(*) FROM os_fulfilment WHERE request_id=?",request));var snapshot=db.one("SELECT * FROM os_catalog_workflow_order WHERE request_id=?",request);assertEquals(body.get("revision"),snapshot.get("offering_revision"));assertTrue(snapshot.get("steps").toString().contains("Prepare <script>"));assertFalse(snapshot.get("steps").toString().contains("Changed after order"));}
  String first=ts.getFirst().get("task_id").toString(),last=ts.getLast().get("task_id").toString();assertEquals(409,h.json("POST",tasksApi(request),taskBody(h,request,last,"claim"),auth("WorkflowTwo")).statusCode());act(h,request,first,"claim","WorkflowOne","");assertEquals("fulfilling",state(h,request));act(h,request,first,"complete","WorkflowOne","Prepared and verified");assertEquals(1L,((Number)progress(h,request,"WorkflowBuyer").get("completed")).longValue());act(h,request,last,"claim","WorkflowTwo","");act(h,request,last,"complete","WorkflowTwo","Delivered successfully");assertEquals("complete",state(h,request));assertEquals(0L,((Number)progress(h,request,"WorkflowBuyer").get("remaining")).longValue());new Store(h.environment);assertEquals("complete",state(h,request));assertEquals(2,objects(tasks(h,request).get("tasks")).size());assertEquals(204,h.json("DELETE","/api/now/table/sc_request/"+request,map(),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_catalog_workflow_order WHERE request_id=?",request));}
  String legacy=order(h,o,orderBody(h,o));assertEquals(404,h.json("POST","/api/openservice/requests/"+legacy+"/workflow",map("record_revision",0),auth("admin")).statusCode());assertNull(parsed(h.get("/api/openservice/requests/"+legacy+"/workflow",auth("WorkflowBuyer"))).get("result"));send(h,o,command(h,o,"enable"));String waived=order(h,o,orderBody(h,o));for(var t:objects(tasks(h,waived).get("tasks"))){String id=t.get("task_id").toString();act(h,waived,id,"cancel","admin","Work superseded");act(h,waived,id,"waive","admin","Reviewed alternative delivery");}assertEquals("open",state(h,waived));reconcile(h,waived);assertEquals("fulfilling",state(h,waived));reconcile(h,waived);reconcile(h,waived);assertEquals("complete",state(h,waived));assertEquals(2L,((Number)progress(h,waived,"WorkflowBuyer").get("waived")).longValue());assertTrue(html(h.get("/record/sc_request/"+waived,auth("WorkflowBuyer"))).contains("2 requirements waived"));String waivedActive=order(h,o,orderBody(h,o));for(var t:objects(tasks(h,waivedActive).get("tasks")))act(h,waivedActive,t.get("task_id").toString(),"waive","admin","Requirement no longer needed");reconcile(h,waivedActive);assertEquals(200,h.json("PATCH","/api/now/table/sc_request/"+waivedActive,map("state","complete"),auth("admin")).statusCode());for(var t:objects(tasks(h,waivedActive).get("tasks")))assertEquals("cancelled",t.get("state"),"Completed catalogue orders must settle unfinished waived work");assertEquals(204,h.json("DELETE","/api/now/table/sc_request/"+waivedActive,map(),auth("admin")).statusCode());
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  var groups=setup(h);String o=offering(h),g=groups.getFirst();assertEquals(403,h.get(api(o),auth("WorkflowBuyer")).statusCode());assertEquals(403,h.json("POST",api(o),command(h,o,"disable"),auth("WorkflowOne")).statusCode());assertEquals(404,h.get(api("f".repeat(32)),auth("admin")).statusCode());assertEquals(405,h.json("PUT",api(o),map(),auth("admin")).statusCode());assertEquals(400,h.get(api(o)+"?extra=x",auth("admin")).statusCode());assertEquals(400,h.json("POST",api(o),command(h,o,"enable"),auth("admin")).statusCode());assertEquals(400,h.json("POST",api(o),map("operation","wrong"),auth("admin")).statusCode());var incomplete=command(h,o,"add");assertEquals(400,h.json("POST",api(o),incomplete,auth("admin")).statusCode());var stale=command(h,o,"disable");String a=add(h,o,g,"First"),b=add(h,o,g,"Second");assertEquals(409,h.json("POST",api(o),stale,auth("admin")).statusCode());
  var invalid=command(h,o,"add");invalid.putAll(map("summary","Valid","details","Instructions","group_id",g));for(var field:List.of(map("summary",""),map("details","x".repeat(4001)),map("group_id",""),map("revision",-1),map("extra",1))){var bad=new LinkedHashMap<>(invalid);bad.putAll(field);assertEquals(400,h.json("POST",api(o),bad,auth("admin")).statusCode());}invalid.put("group_id","f".repeat(32));assertEquals(404,h.json("POST",api(o),invalid,auth("admin")).statusCode());
  for(var pair:List.of(List.of("up",a),List.of("down",b),List.of("edit","f".repeat(32)))){var bad=command(h,o,pair.get(0));bad.put("step_id",pair.get(1));if(pair.get(0).equals("edit"))bad.putAll(map("summary","No","details","No","group_id",g));assertEquals(pair.get(0).equals("edit")?404:400,h.json("POST",api(o),bad,auth("admin")).statusCode());}
  step(h,o,"down",a);assertEquals(a,steps(h,o).getLast().get("step_id"));step(h,o,"up",a);assertEquals(a,steps(h,o).getFirst().get("step_id"));send(h,o,command(h,o,"enable"));step(h,o,"remove",a);var remove=command(h,o,"remove");remove.put("step_id",b);assertEquals(400,h.json("POST",api(o),remove,auth("admin")).statusCode());send(h,o,command(h,o,"disable"));step(h,o,"remove",b);assertTrue(steps(h,o).isEmpty());
  for(int n=0;n<20;n++)add(h,o,g,"Bounded "+n);var tooMany=command(h,o,"add");tooMany.putAll(map("summary","Overflow","details","Instructions","group_id",g));assertEquals(400,h.json("POST",api(o),tooMany,auth("admin")).statusCode());String url="/admin/catalogue/"+o+"/workflow";assertEquals(403,h.form(url,command(h,o,"disable"),auth("admin")).statusCode());assertEquals(400,h.protectedForm(url,map("revision",object(settings(h,o).get("offering")).get("revision")),auth("admin")).statusCode());assertEquals(302,h.protectedForm(url,command(h,o,"enable"),auth("admin")).statusCode());
  String request=order(h,o,orderBody(h,o));assertEquals(400,h.json("POST","/api/openservice/requests/"+request+"/workflow",map(),auth("admin")).statusCode());assertEquals(403,h.json("POST","/api/openservice/requests/"+request+"/workflow",map("record_revision",0),auth("WorkflowBuyer")).statusCode());assertEquals(400,h.get("/api/openservice/requests/"+request+"/workflow?x=y",auth("admin")).statusCode());assertEquals(404,h.get("/api/openservice/requests/"+"f".repeat(32)+"/workflow",auth("admin")).statusCode());
 }
 static void authority(WorkflowSupport h)throws Exception{
  var groups=setup(h);String o=offering(h);add(h,o,groups.getFirst(),"Controlled step");send(h,o,command(h,o,"enable"));String request=order(h,o,orderBody(h,o)),task=objects(tasks(h,request).get("tasks")).getFirst().get("task_id").toString();Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"sc_request");}
  for(var constraint:List.of(map("record_roles",map("update",List.of("admin"))),map("field_rules",map("state",map("type","string","write_roles",List.of("admin")))),map("transition_rules",map("fulfilling",map("min_approvals",1))))){var changed=new LinkedHashMap<>(original);changed.putAll(constraint);ReferencePickerAcceptance.writeSchema(h,"sc_request",changed);try{int code=constraint.containsKey("transition_rules")?409:403;assertEquals(code,h.json("POST",tasksApi(request),taskBody(h,request,task,"claim"),auth("WorkflowOne")).statusCode());assertEquals("queued",WorkTasksAcceptance.task(tasks(h,request),task).get("state"));assertEquals("open",state(h,request));}finally{ReferencePickerAcceptance.writeSchema(h,"sc_request",original);}}
  var hidden=new LinkedHashMap<>(original);hidden.put("field_rules",map("state",map("type","string","read_roles",List.of("admin","agent"))));ReferencePickerAcceptance.writeSchema(h,"sc_request",hidden);try{assertEquals(403,h.get("/api/openservice/requests/"+request+"/workflow",auth("WorkflowBuyer")).statusCode());assertFalse(html(h.get("/record/sc_request/"+request,auth("WorkflowBuyer"))).contains("id=\"catalogue-progress\""));}finally{ReferencePickerAcceptance.writeSchema(h,"sc_request",original);}
  act(h,request,task,"claim","WorkflowOne","");var gated=new LinkedHashMap<>(original);gated.put("transition_rules",map("complete",map("min_approvals",1)));ReferencePickerAcceptance.writeSchema(h,"sc_request",gated);try{var finish=taskBody(h,request,task,"complete");finish.put("outcome","Done");assertEquals(409,h.json("POST",tasksApi(request),finish,auth("WorkflowOne")).statusCode());assertEquals("working",WorkTasksAcceptance.task(tasks(h,request),task).get("state"));try(var db=h.store.open()){var admin=ApprovalTest.as(db,"admin");String approval=Approvals.request(db,"sc_request",request,admin,map("expected_revision",Service.record(db,"sc_request",request).get("revision"),"approver","WorkflowTwo","target_state","complete","reason","Review final delivery")).get("approval_id").toString();Approvals.decide(db,"sc_request",request,approval,ApprovalTest.as(db,"WorkflowTwo"),map("decision","approved","comment","Approved"));db.connection.commit();}act(h,request,task,"complete","WorkflowOne","Done and approved");}finally{ReferencePickerAcceptance.writeSchema(h,"sc_request",original);}
  String recovery=order(h,o,orderBody(h,o)),recoveryTask=objects(tasks(h,recovery).get("tasks")).getFirst().get("task_id").toString();act(h,recovery,recoveryTask,"cancel","admin","Alternative delivery needs review");ReferencePickerAcceptance.writeSchema(h,"sc_request",gated);try{act(h,recovery,recoveryTask,"waive","admin","Waiver must persist before its revised case can be approved");assertEquals("open",state(h,recovery));reconcile(h,recovery);assertEquals("fulfilling",state(h,recovery));try(var db=h.store.open()){var admin=ApprovalTest.as(db,"admin");String approval=Approvals.request(db,"sc_request",recovery,admin,map("expected_revision",Service.record(db,"sc_request",recovery).get("revision"),"approver","WorkflowTwo","target_state","complete","reason","Review waived requirement")).get("approval_id").toString();Approvals.decide(db,"sc_request",recovery,approval,ApprovalTest.as(db,"WorkflowTwo"),map("decision","approved","comment","Approved alternative"));db.connection.commit();}reconcile(h,recovery);assertEquals("complete",state(h,recovery));}finally{ReferencePickerAcceptance.writeSchema(h,"sc_request",original);}
  long records;try(var db=h.store.open()){records=db.count("SELECT COUNT(*) FROM os_record");}
  for(String broken:List.of("open","fulfilling","complete")){var schema=object(JSON.readValue(JSON.writeValueAsString(original),Map.class));object(schema.get("flow")).put(broken,broken.equals("complete")?List.of("open"):List.of());ReferencePickerAcceptance.writeSchema(h,"sc_request",schema);try{assertEquals(400,h.json("POST","/api/openservice/catalogue/"+o+"/order",orderBody(h,o),auth("WorkflowBuyer")).statusCode());try(var db=h.store.open()){assertEquals(records,db.count("SELECT COUNT(*) FROM os_record"));}}finally{ReferencePickerAcceptance.writeSchema(h,"sc_request",original);}}
  var schema=object(JSON.readValue(JSON.writeValueAsString(original),Map.class));var states=new LinkedHashMap<String,Object>();states.put("fulfilling","Fulfilling");states.putAll(object(schema.get("states")));schema.put("states",states);ReferencePickerAcceptance.writeSchema(h,"sc_request",schema);try{assertEquals(400,h.json("POST","/api/openservice/catalogue/"+o+"/order",orderBody(h,o),auth("WorkflowBuyer")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"sc_request",original);}
  assertEquals(204,h.json("DELETE","/api/now/table/sys_user_group/"+groups.getFirst(),map(),auth("admin")).statusCode());assertEquals(400,h.json("POST","/api/openservice/catalogue/"+o+"/order",orderBody(h,o),auth("WorkflowBuyer")).statusCode());send(h,o,command(h,o,"disable"));assertEquals(400,h.json("POST",api(o),command(h,o,"enable"),auth("admin")).statusCode());
 }
}
